import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CvydjLy7.js";const m=JSON.parse('{"title":"8.12 选型与问题速查","description":"","frontmatter":{"title":"8.12 选型与问题速查"},"headers":[{"level":3,"title":"该选哪个","slug":"该选哪个","link":"#该选哪个","children":[]},{"level":3,"title":"问题速查","slug":"问题速查","link":"#问题速查","children":[]}],"relativePath":"ch08/12.md","filePath":"ch08/12.md","lastUpdated":1789497795000}'),a={name:"ch08/12.md"};function c(n,t,i,l,s,b){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_8-12-选型与问题速查" tabindex="-1">8.12 选型与问题速查 <a class="header-anchor" href="#_8-12-选型与问题速查" aria-label="Permalink to &quot;8.12 选型与问题速查&quot;">​</a></h1><h3 id="该选哪个" tabindex="-1">该选哪个 <a class="header-anchor" href="#该选哪个" aria-label="Permalink to &quot;该选哪个&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的需求</th><th>选择</th></tr></thead><tbody><tr><td>事件要能被多个消费者独立重放</td><td>Kafka</td></tr><tr><td>需要按业务键保证顺序</td><td>Kafka（key 用业务 ID），按分区数并行</td></tr><tr><td>一条消息要根据不同条件路由到不同队列</td><td>RabbitMQ（topic / headers 交换机）</td></tr><tr><td>任务分发，处理完就删，需要优先级、延迟队列</td><td>RabbitMQ</td></tr><tr><td>日志、埋点、变更流这类高吞吐数据管道</td><td>Kafka</td></tr><tr><td>只是想给浏览器推消息</td><td>都不需要，WebSocket 足够</td></tr></tbody></table><h3 id="问题速查" tabindex="-1">问题速查 <a class="header-anchor" href="#问题速查" aria-label="Permalink to &quot;问题速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>Kafka 日志里没报错，但业务数据不再更新</td><td>一条坏消息在无限重试，分区被堵住</td><td>配 <code>DefaultErrorHandler</code> + 重试上限 + 死信</td></tr><tr><td>死信主题里找不到消息</td><td>默认后缀是 <code>-dlt</code>（连字符），不是 <code>.DLT</code></td><td>显式指定目的地</td></tr><tr><td>同一活动的事件顺序乱了</td><td>生产者没指定 key，消息轮询进各分区</td><td><code>send(topic, String.valueOf(id), event)</code></td></tr><tr><td><code>send()</code> 没报错但消息丢了</td><td>返回的 Future 没被 await 或挂回调</td><td>挂 <code>whenComplete</code> 或 <code>get(timeout)</code></td></tr><tr><td>RabbitMQ 消息发出去了但没人收</td><td>路由键没有绑定，且没开 <code>mandatory</code></td><td>开 <code>publisher-returns</code> + <code>template.mandatory</code>，看退回日志</td></tr><tr><td>消息在 RabbitMQ 管理界面里是乱码</td><td>用了默认的 <code>SimpleMessageConverter</code>（JDK 序列化）</td><td>换 <code>JacksonJsonMessageConverter</code></td></tr><tr><td>手工 <code>new</code> 的 <code>RabbitTemplate</code> 报只支持 String/byte[]</td><td>没手工挂 <code>MessageConverter</code> Bean</td><td><code>template.setMessageConverter(...)</code></td></tr><tr><td>同一条消息被反复处理</td><td>监听器抛异常后无限重投</td><td><code>default-requeue-rejected: false</code> 或抛 <code>AmqpRejectAndDontRequeueException</code></td></tr><tr><td><code>@KafkaListener</code> 高并发没生效</td><td>分区数少于线程数</td><td>加分区（只能增不能减）</td></tr><tr><td>WebSocket 单机能用、多实例收不到</td><td><code>enableSimpleBroker</code> 是进程内的</td><td>换 <code>enableStompBrokerRelay</code></td></tr><tr><td>客户端 <code>subscribe</code> 后立刻发消息收不到</td><td>订阅是异步的</td><td>用回执（需真 broker）或重发直到收到</td></tr><tr><td>import 报找不到 <code>WebSocketStompClient</code></td><td>Framework 7 换了包</td><td>用 <code>org.springframework.web.socket.messaging.WebSocketStompClient</code></td></tr><tr><td>老的 <code>KafkaProperties</code> import 编译不过</td><td>Boot 4 按技术栈拆了模块</td><td>换成 <code>org.springframework.boot.kafka.autoconfigure.KafkaProperties</code></td></tr><tr><td><code>TestRabbitTemplate</code> 一直连 broker</td><td>连接工厂是真实的，或 Bean 化后被后处理替换</td><td>用 mock 工厂，并在 <code>@BeforeEach</code> 里重新 <code>setConnectionFactory</code></td></tr></tbody></table><hr>',6)])])}const p=e(a,[["render",c]]);export{m as __pageData,p as default};
